Write a Python function that computes drain current given the type ('D' or 'E'), parameters, and V_GS.

def compute_drain_current(m_type, v_gs, param1, param2):
    if m_type == 'D':
        i_dss, v_p = param1, param2
        return i_dss * ((1 - (v_gs / v_p)) ** 2)
    elif m_type == 'E':
        v_t, k = param1, param2
        if v_gs < v_t:
            return 0.0
        return k * ((v_gs - v_t) ** 2)
    return None

Write a Python function to calculate JFET drain current using Shockley's equation.

def shockley_id(idss, v_p, v_gs):
    if v_gs <= v_p:
        return 0.0
    if v_gs >= 0:
        return idss
    return idss * ((1 - (v_gs / v_p)) ** 2)

