import math
def bridge_rectifier_voltage(v_rms):
    v_peak = v_rms * math.sqrt(2)
    v_dc = (2 * v_peak) / math.pi
    return round(v_peak, 2), round(v_dc, 2)
print(bridge_rectifier_voltage(12.0)) # Expected: (16.97, 10.8)

def filter_ripple_voltage(v_dc, freq, r_load, c_farads):
    v_r = v_dc / (2 * freq * r_load * c_farads)
    return round(v_r, 3)
print(filter_ripple_voltage(10.8, 50, 1000, 0.0001))
# Expected: 1.08
